<script setup lang="ts">
import { RANGE_PRESETS, resolveRange, rangeLabel, type RangePreset } from '~/shared/date-range'
// Payments out of the group: vendors, landlord, purchases… Each payment gets a voucher PDF and is posted to the books.
// Reconcile against an uploaded spreadsheet or balance sheet so the numbers stay true.
useHead({ title: 'Payments' })
const route = useRoute(), router = useRouter()
const TABS = [['payments', 'Payments'], ['balance', 'Balance'], ['categories', 'Categories']] as const
const tab = computed(() => (TABS.some((t) => t[0] === route.query.t) ? String(route.query.t) : 'payments'))
const go = (t: string) => router.replace({ query: { ...route.query, t } })
// The period everything on the page (list, totals, balance, export) is for.
const preset = ref<RangePreset>('ytd'); const custom = reactive({ from: '', to: '' })
const range = computed(() => resolveRange(preset.value, new Date(), custom))
watch(preset, (p) => { if (p === 'custom' && !custom.from) { const r = resolveRange('this_month'); custom.from = r.from; custom.to = new Date().toISOString().slice(0, 10) } })
const cat = ref('')
interface Row { id: string; number: string; paid_on: string; payee: string; category: string; description: string | null; amount: number; currency: string; method: string | null; reference: string | null; voucher_id: string | null; attachment_id: string | null; entity: string | null; entity_id: string | null }
const { data, refresh } = await useFetch<{ rows: Row[]; options: { entities: { id: string; name: string }[]; accounts: { id: string; name: string; entity_id: string; currency: string }[]; categories: string[]; payees: string[] }; receipt_ai: boolean }>('/api/expenses')
const money = (v: number, c: string) => new Intl.NumberFormat('en-US', { style: 'currency', currency: c, maximumFractionDigits: 2 }).format(v)
interface Checks { by_id: Record<string, { bank: 'matched' | 'missing' | 'no_statement' | 'no_account'; bank_txn?: { date: string; description: string }; receipt: string | null; receipt_issues: string[] }>; unlogged: { date: string; account: string; description: string; amount: number; currency: string }[]; financials: { entity: string; period: string; currency: string; logged: number; statement_costs: number; text: string }[]; summary: { payments: number; bank_matched: number; bank_missing: number; bank_no_statement: number; receipt_mismatch: number; unlogged: number; financials: number } }
const { data: chk, refresh: refreshChk } = await useFetch<Checks>('/api/expenses/checks', { key: 'pay-checks' })
const panel = ref<'' | 'missing' | 'receipt' | 'unlogged' | 'financials'>('')
const issueRows = computed(() => (data.value?.rows ?? []).filter((r) => panel.value === 'missing' ? chk.value?.by_id[r.id]?.bank === 'missing' : panel.value === 'receipt' ? ['mismatch', 'unreadable'].includes(chk.value?.by_id[r.id]?.receipt ?? '') : false))
const BANK: Record<string, string> = { matched: 'In bank', missing: 'Not in bank', no_statement: 'Awaiting statement', no_account: '' }
const checking = ref('')
async function checkReceipt(r: Row) { checking.value = r.id; try { await $fetch('/api/expenses/' + r.id + '/check-receipt', { method: 'POST' }); await refreshChk() } catch (e) { alert((e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not read the receipt.') } finally { checking.value = '' } }
// receipt read in the form
interface Read { number: string | null; amount: number | null; currency: string | null; date: string | null; payee: string | null; readable: boolean }
const scan = reactive({ busy: false, read: null as Read | null, msg: '' })
async function pickFile(ev: Event) {
  file.value = (ev.target as HTMLInputElement).files?.[0] ?? null; scan.read = null; scan.msg = ''
  if (!file.value || !data.value?.receipt_ai) return
  scan.busy = true; const fd = new FormData(); fd.append('file', file.value)
  try {
    const r = await $fetch<Read>('/api/expenses/scan', { method: 'POST', body: fd }); scan.read = r
    if (r.readable) { if (!f.amount && r.amount) f.amount = r.amount; if (!f.reference && r.number) f.reference = r.number; if (!f.payee && r.payee) f.payee = r.payee; if (r.currency && ['USD', 'NGN', 'GBP', 'EUR'].includes(r.currency) && !f.amount) f.currency = r.currency }
  } catch (e) { scan.msg = (e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not read the receipt.' } finally { scan.busy = false }
}
const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '')
const scanIssues = computed(() => { const r = scan.read; if (!r) return []; if (!r.readable) return ['This file does not look like a receipt or invoice.']; const out: string[] = []
  if (r.currency && r.currency !== f.currency) out.push('Receipt is in ' + r.currency + ', payment is in ' + f.currency + '.')
  if (r.amount !== null && f.amount !== '' && Math.abs(r.amount - Number(f.amount)) >= 0.01) out.push('Receipt total is ' + money(r.amount, r.currency || f.currency) + ', you entered ' + money(Number(f.amount), f.currency) + '.')
  if (r.number && f.reference && !norm(f.reference).includes(norm(r.number)) && !norm(r.number).includes(norm(f.reference))) out.push('Receipt number is ' + r.number + ', reference entered is ' + f.reference + '.')
  return out })
const q = ref(''); const ent = ref('')
const shown = computed(() => (data.value?.rows ?? []).filter((r) => (!ent.value || r.entity_id === ent.value) && r.paid_on >= range.value.from && r.paid_on <= range.value.to && (!cat.value || r.category === cat.value) && (!q.value || (r.payee + ' ' + r.category + ' ' + (r.description ?? '') + ' ' + r.number).toLowerCase().includes(q.value.toLowerCase()))))
const totals = computed(() => { const m: Record<string, number> = {}; for (const r of shown.value) m[r.currency] = (m[r.currency] ?? 0) + r.amount; return m })
const byCat = computed(() => { const m = new Map<string, number>(); for (const r of shown.value.filter((x) => x.currency === (Object.keys(totals.value)[0] ?? 'USD'))) m.set(r.category, (m.get(r.category) ?? 0) + r.amount); return [...m.entries()].map(([label, value]) => ({ label, value })) })
const blank = () => ({ open: false, paid_on: new Date().toISOString().slice(0, 10), entity_id: '', payee: '', category: 'Software & subscriptions', description: '', amount: '' as string | number, currency: 'USD', method: 'Bank transfer', bank_account_id: '', reference: '' })
const f = reactive(blank()); const file = ref<File | null>(null); const msg = ref(''); const busy = ref(false); const dupe = ref('')
function open(prefill?: Partial<ReturnType<typeof blank>>) { Object.assign(f, blank(), prefill ?? {}, { open: true }); file.value = null; msg.value = ''; dupe.value = ''; scan.read = null; scan.msg = '' }
async function save(force = false) { busy.value = true; msg.value = ''; const fd = new FormData(); for (const [k, v] of Object.entries(f)) if (k !== 'open') fd.append(k, String(v)); if (force) fd.append('force', '1'); if (file.value) fd.append('file', file.value)
  try { await $fetch('/api/expenses', { method: 'POST', body: fd }); f.open = false; await Promise.all([refresh(), refreshChk()]) } catch (e) { const er = e as { statusCode?: number; data?: { data?: { error?: { message?: string } } } }; if (er.statusCode === 409) dupe.value = er.data?.data?.error?.message ?? 'Possible duplicate.'; else msg.value = er.data?.data?.error?.message ?? 'Could not save.' } finally { busy.value = false } }
async function del(r: Row) { if (!confirm('Delete ' + r.number + ' (' + r.payee + ')? Its book entries are removed; the voucher PDF stays in Documents.')) return; const fd = new FormData(); fd.append('delete_id', r.id); await $fetch('/api/expenses', { method: 'POST', body: fd }); await Promise.all([refresh(), refreshChk()]) }
// Export and balance for the chosen period.
const exportUrl = (format: 'csv' | 'xlsx') => '/api/expenses/export?' + new URLSearchParams({ from: range.value.from, to: range.value.to, entity_id: ent.value, category: cat.value, format, label: rangeLabel(preset.value, range.value) }).toString()
const { data: bal, pending: balBusy, refresh: refreshBal } = await useLazyFetch<{ accounts: { id: string; name: string; currency: string; entity: string | null; statements: { from: string; to: string; full: boolean } | null; money_out: number; explained: number; unexplained: number; unexplained_count: number; by: { payments: number; deployments: number; team_pay: number }; logged_not_in_bank: number; logged_not_in_bank_count: number }[]; categories: { name: string; currency: string; line: string; line_label: string; known: boolean; logged: number; journal: number; difference: number }[]; lines: { line: string; label: string; totals: Record<string, number> }[] }>('/api/expenses/balance', { query: computed(() => ({ from: range.value.from, to: range.value.to })), server: false })
// Categories: built-in ones plus the workspace's own, each tied to a statement line.
interface Cat { id: string | null; name: string; line: string; builtin: boolean; archived: boolean; payments: number; totals: Record<string, number> }
const { data: cats, refresh: refreshCats } = await useLazyFetch<{ categories: Cat[]; lines: Record<string, string> }>('/api/expenses/categories', { server: false })
const nc = reactive({ name: '', line: 'opex_ga', msg: '', busy: false, inForm: false })
async function addCat(useInForm = false) {
  nc.busy = true; nc.msg = ''
  try { const r = await $fetch<{ name: string }>('/api/expenses/categories', { method: 'POST', body: { name: nc.name, statement_line: nc.line } }); await Promise.all([refresh(), refreshCats()]); if (useInForm) { f.category = r.name; nc.inForm = false }; nc.name = '' }
  catch (e) { nc.msg = (e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not add the category.' } finally { nc.busy = false }
}
async function setCat(c: Cat, body: Record<string, unknown>) { await $fetch('/api/expenses/categories', { method: 'POST', body: { id: c.id, ...body } }); await Promise.all([refresh(), refreshCats()]) }
watch(() => f.category, (v) => { if (v === '__new') { nc.inForm = true; f.category = data.value?.options.categories[0] ?? 'Other' } })
void refreshBal
// reconciliation
interface Rec { summary: string; sheet_kind: string; totals: { logged: number; sheet: number; difference: number; currency: string }; matched: { log_number: string; sheet_row: string; note?: string }[]; missing_in_log: { date: string; payee: string; amount: number; currency: string; category?: string; sheet_row: string }[]; missing_in_sheet: { log_number: string; note?: string }[]; mismatched: { log_number: string; sheet_row: string; issue: string }[]; category_checks: { category: string; logged: number; sheet: number; note?: string }[] }
const rc = reactive({ open: false, from: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().slice(0, 10), to: new Date().toISOString().slice(0, 10), entity_id: '', busy: false, msg: '' }); const rfile = ref<File | null>(null); const rec = ref<Rec | null>(null)
async function reconcile() { if (!rfile.value) return; rc.busy = true; rc.msg = ''; rec.value = null; const fd = new FormData(); fd.append('file', rfile.value); fd.append('from', rc.from); fd.append('to', rc.to); fd.append('entity_id', rc.entity_id)
  try { rec.value = await $fetch<Rec>('/api/expenses/reconcile', { method: 'POST', body: fd }) } catch (e) { rc.msg = (e as { data?: { data?: { error?: { message?: string } } } }).data?.data?.error?.message ?? 'Could not reconcile. Check the file and try again.' } finally { rc.busy = false } }
</script>
<template>
  <section v-if="data">
    <div class="hd"><div><p class="label">Financials</p><h1>Payments</h1><p class="lead">Log what the group pays out: vendors, rent, purchases, fees. Each payment gets a voucher PDF, is posted to the journals, and can be reconciled against your spreadsheets.</p></div>
      <div class="acts"><details class="dd"><summary class="btn secondary">Export</summary><div class="ddm"><a :href="exportUrl('xlsx')">Excel (.xlsx)</a><a :href="exportUrl('csv')">CSV</a><span>{{ rangeLabel(preset, range) }}{{ ent ? ' · one entity' : '' }}{{ cat ? ' · ' + cat : '' }}</span></div></details><button class="btn secondary" @click="rc.open = true; rec = null">Reconcile with a spreadsheet</button><button class="btn" @click="open()">Log a payment</button></div></div>
    <div class="flt top"><select v-model="preset" aria-label="Period"><option v-for="p in RANGE_PRESETS" :key="p[0]" :value="p[0]">{{ p[1] }}</option></select><template v-if="preset === 'custom'"><input v-model="custom.from" type="date" aria-label="From"><span class="to">to</span><input v-model="custom.to" type="date" aria-label="To"></template><span v-else-if="preset !== 'all'" class="rg">{{ range.from }} to {{ range.to }}</span>
      <select v-model="ent"><option value="">All entities</option><option v-for="e in data.options.entities" :key="e.id" :value="e.id">{{ e.name }}</option></select>
      <select v-model="cat"><option value="">All categories</option><option v-for="c in data.options.categories" :key="c" :value="c">{{ c }}</option></select></div>
    <nav class="tabs" aria-label="Payments"><button v-for="t in TABS" :key="t[0]" type="button" :class="{ on: tab === t[0] }" @click="go(t[0])">{{ t[1] }}</button></nav>
    <template v-if="tab === 'payments'">
    <div class="kp"><div class="k"><span>Total in view</span><b>{{ Object.keys(totals).length ? Object.entries(totals).map(([c, v]) => money(v, c)).join(' · ') : '—' }}</b><em>{{ shown.length }} payment{{ shown.length === 1 ? '' : 's' }}</em></div>
      <div v-if="byCat.length" class="k wide"><DonutChart title="By category" total-label="Total" :currency="Object.keys(totals)[0]" :segments="byCat" /></div></div>
    <div v-if="chk && chk.summary.payments" class="chks">
      <span class="ck ok">✓ {{ chk.summary.bank_matched }} matched to the bank</span>
      <button v-if="chk.summary.bank_missing" class="ck bad" :class="{ on: panel === 'missing' }" @click="panel = panel === 'missing' ? '' : 'missing'">⚠ {{ chk.summary.bank_missing }} not in the bank statement</button>
      <span v-if="chk.summary.bank_no_statement" class="ck" title="Import the bank statement for these dates in Banking to check them">{{ chk.summary.bank_no_statement }} awaiting a bank statement</span>
      <button v-if="chk.summary.receipt_mismatch" class="ck bad" :class="{ on: panel === 'receipt' }" @click="panel = panel === 'receipt' ? '' : 'receipt'">⚠ {{ chk.summary.receipt_mismatch }} receipt{{ chk.summary.receipt_mismatch === 1 ? '' : 's' }} don't match</button>
      <button v-if="chk.summary.unlogged" class="ck bad" :class="{ on: panel === 'unlogged' }" @click="panel = panel === 'unlogged' ? '' : 'unlogged'">⚠ {{ chk.summary.unlogged }} bank payment{{ chk.summary.unlogged === 1 ? '' : 's' }} not logged</button>
      <button v-if="chk.summary.financials" class="ck bad" :class="{ on: panel === 'financials' }" @click="panel = panel === 'financials' ? '' : 'financials'">⚠ {{ chk.summary.financials }} period{{ chk.summary.financials === 1 ? '' : 's' }} over the financials</button>
      <span v-if="!chk.summary.bank_missing && !chk.summary.receipt_mismatch && !chk.summary.unlogged && !chk.summary.financials" class="ck ok">✓ Nothing to fix</span>
    </div>
    <div v-if="panel && chk" class="card cpan">
      <template v-if="panel === 'missing' || panel === 'receipt'"><p class="s">{{ panel === 'missing' ? 'These payments are not in the imported bank statement for that account and date (within ' + 7 + ' days, same amount). Check the amount, date or account.' : 'The attached receipt or invoice does not agree with what was logged.' }}</p>
        <div v-for="r in issueRows" :key="r.id" class="ri"><span><b>{{ r.number }}</b> · {{ r.payee }} · {{ money(r.amount, r.currency) }} · {{ r.paid_on }}<template v-if="panel === 'receipt'"><br><em>{{ chk.by_id[r.id]?.receipt_issues.join(' ') }}</em></template></span><a v-if="panel === 'receipt' && r.attachment_id" :href="'/api/expenses/doc/' + r.attachment_id" target="_blank">Open receipt</a></div></template>
      <template v-else-if="panel === 'unlogged'"><p class="s">Money that left your bank accounts (last 12 months) that no logged payment or deployment explains.</p>
        <div v-for="(u, i) in chk.unlogged" :key="i" class="ri"><span>{{ u.date }} · {{ u.account }} · <b>{{ money(u.amount, u.currency) }}</b><br><em>{{ u.description }}</em></span><button class="lk" @click="open({ paid_on: u.date, amount: u.amount, currency: ['USD', 'NGN', 'GBP', 'EUR'].includes(u.currency) ? u.currency : 'USD', description: u.description })">Log it</button></div></template>
      <template v-else><p class="s">Payments logged for these periods add up to more than the costs in the financial statements. One of them is wrong.</p>
        <div v-for="(x, i) in chk.financials" :key="i" class="ri"><span><b>{{ x.entity }} · {{ x.period }}</b><br><em>{{ x.text }}</em></span><NuxtLink to="/financials">Open Financials</NuxtLink></div></template>
    </div>
    <div class="flt"><input v-model="q" placeholder="Search payee, category, voucher no."></div>
    <div class="card tc"><table v-if="shown.length" class="table"><thead><tr><th>Date</th><th>Voucher</th><th>Paid to</th><th>Category</th><th>Entity</th><th class="n">Amount</th><th>Records</th><th /></tr></thead><tbody>
      <tr v-for="r in shown" :key="r.id"><td>{{ r.paid_on }}</td><td>{{ r.number }}</td><td><b>{{ r.payee }}</b><span v-if="r.description" class="s">{{ r.description }}</span></td><td>{{ r.category }}</td><td>{{ r.entity ?? '—' }}</td><td class="n"><b>{{ money(r.amount, r.currency) }}</b><span class="s">{{ [r.method, r.reference].filter(Boolean).join(' · ') }}</span></td>
        <td><a v-if="r.voucher_id" :href="'/api/expenses/doc/' + r.voucher_id" target="_blank">Voucher</a><a v-if="r.attachment_id" :href="'/api/expenses/doc/' + r.attachment_id" target="_blank" class="ml">Invoice</a>
          <div v-if="chk?.by_id[r.id]" class="bdg"><span v-if="BANK[chk.by_id[r.id]!.bank]" :class="chk.by_id[r.id]!.bank" :title="chk.by_id[r.id]!.bank_txn ? chk.by_id[r.id]!.bank_txn!.date + ' · ' + chk.by_id[r.id]!.bank_txn!.description : ''">{{ BANK[chk.by_id[r.id]!.bank] }}</span>
            <span v-if="chk.by_id[r.id]!.receipt === 'match'" class="matched">Receipt ✓</span><span v-else-if="chk.by_id[r.id]!.receipt" class="missing" :title="chk.by_id[r.id]!.receipt_issues.join(' ')">Receipt ⚠</span>
            <button v-else-if="r.attachment_id && data?.receipt_ai" class="lk" :disabled="checking === r.id" @click="checkReceipt(r)">{{ checking === r.id ? 'Reading…' : 'Check receipt' }}</button></div></td><td><button class="lk" @click="del(r)">Delete</button></td></tr></tbody></table>
      <EmptyState v-else compact icon="billing" title="No payments logged" text="Log rent, vendor bills, software and purchases. Each one gets a voucher and is posted to the books."><button class="btn" @click="open()">Log a payment</button></EmptyState></div>
    </template>
    <template v-else-if="tab === 'balance'">
      <p class="s intro">For {{ rangeLabel(preset, range).toLowerCase() }}: what left each bank account and what explains it, and each category against the journals. Import bank statements in Banking for accounts that show none.</p>
      <div class="card tc"><div class="chh"><h3>Bank accounts</h3><span class="s">Money out of the bank, matched to logged payments, deployments and team pay</span></div>
        <table v-if="bal?.accounts.length" class="table" data-nosearch><thead><tr><th>Account</th><th>Statements</th><th class="n">Money out</th><th class="n">Payments</th><th class="n">Deployments</th><th class="n">Team pay</th><th class="n">Not explained</th><th class="n">Logged, not in bank</th></tr></thead>
          <tbody><tr v-for="a in bal.accounts" :key="a.id"><td><b>{{ a.name }}</b><span class="s">{{ a.entity ?? '—' }} · {{ a.currency }}</span></td>
            <td><span v-if="!a.statements" class="pl bad">None for this period</span><span v-else-if="!a.statements.full" class="pl">{{ a.statements.from }} to {{ a.statements.to }}</span><span v-else class="pl">Complete</span></td>
            <td class="n">{{ money(a.money_out, a.currency) }}</td><td class="n">{{ money(a.by.payments, a.currency) }}</td><td class="n">{{ money(a.by.deployments, a.currency) }}</td><td class="n">{{ money(a.by.team_pay, a.currency) }}</td>
            <td class="n"><b :class="{ red: a.unexplained > 0.01 }">{{ money(a.unexplained, a.currency) }}</b><span v-if="a.unexplained_count" class="s">{{ a.unexplained_count }} line{{ a.unexplained_count === 1 ? '' : 's' }}</span></td>
            <td class="n"><b :class="{ red: a.logged_not_in_bank > 0.01 }">{{ money(a.logged_not_in_bank, a.currency) }}</b><span v-if="a.logged_not_in_bank_count" class="s">{{ a.logged_not_in_bank_count }} payment{{ a.logged_not_in_bank_count === 1 ? '' : 's' }}</span></td></tr></tbody></table>
        <p v-else class="s pad">{{ balBusy ? 'Loading…' : 'No bank activity or statements for this period.' }}</p></div>
      <div class="card tc"><div class="chh"><h3>Categories</h3><span class="s">Logged payments against the journals, by financial statement line</span></div>
        <table v-if="bal?.categories.length" class="table" data-nosearch><thead><tr><th>Category</th><th>Statement line</th><th class="n">Logged</th><th class="n">In the journals</th><th class="n">Difference</th></tr></thead>
          <tbody><tr v-for="c in bal.categories" :key="c.name + c.currency"><td><b>{{ c.name }}</b><span v-if="!c.known" class="s">Not a current category</span></td><td>{{ c.line_label }}</td><td class="n">{{ money(c.logged, c.currency) }}</td><td class="n">{{ money(c.journal, c.currency) }}</td><td class="n"><b :class="{ red: Math.abs(c.difference) > 0.01 }">{{ Math.abs(c.difference) > 0.01 ? money(c.difference, c.currency) : 'Balanced' }}</b></td></tr></tbody>
          <tfoot><tr v-for="l in bal.lines" :key="l.line"><td>{{ l.label }}</td><td /><td class="n" colspan="3">{{ Object.entries(l.totals).map(([c, v]) => money(v, c)).join(' · ') }}</td></tr></tfoot></table>
        <p v-else class="s pad">{{ balBusy ? 'Loading…' : 'No payments in this period.' }}</p></div>
    </template>
    <template v-else>
      <div class="card tc"><div class="chh"><h3>Categories</h3><span class="s">Each category rolls up to a line of the financial statements, so payments, journals and statements agree.</span></div>
        <form class="addc" @submit.prevent="addCat()"><input v-model="nc.name" maxlength="60" placeholder="New category, e.g. Recruitment" aria-label="New category"><select v-model="nc.line" aria-label="Statement line"><option v-for="(l, k) in cats?.lines ?? {}" :key="k" :value="k">{{ l }}</option></select><button class="btn" :disabled="nc.busy || nc.name.trim().length < 2">Add category</button><span v-if="nc.msg && !nc.inForm" class="error">{{ nc.msg }}</span></form>
        <table v-if="cats" class="table" data-nosearch><thead><tr><th>Category</th><th>Statement line</th><th class="n">Payments</th><th class="n">Paid</th><th /></tr></thead>
          <tbody><tr v-for="c in cats.categories" :key="c.name" :class="{ off: c.archived }"><td><b>{{ c.name }}</b><span class="s">{{ c.builtin ? 'Built in' : c.archived ? 'Archived: kept on old payments, not offered' : 'Added by your team' }}</span></td>
            <td><select v-if="!c.builtin" :value="c.line" class="ls" @change="setCat(c, { statement_line: ($event.target as HTMLSelectElement).value })"><option v-for="(l, k) in cats.lines" :key="k" :value="k">{{ l }}</option></select><span v-else>{{ cats.lines[c.line] }}</span></td>
            <td class="n">{{ c.payments || '—' }}</td><td class="n">{{ Object.entries(c.totals).map(([k, v]) => money(v, k)).join(' · ') || '—' }}</td>
            <td class="n"><button v-if="!c.builtin" class="lk" @click="setCat(c, { archived: !c.archived })">{{ c.archived ? 'Restore' : 'Archive' }}</button></td></tr></tbody></table></div>
    </template>
    <AppModal :open="f.open" title="Log a payment" wide @close="f.open = false">
      <div class="fm"><div class="g3"><label class="label">Date paid<input v-model="f.paid_on" type="date"></label><label class="label">Paid by (entity)<select v-model="f.entity_id"><option value="">Choose</option><option v-for="e in data.options.entities" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label class="label">Category<select v-model="f.category"><option v-for="c in data.options.categories" :key="c">{{ c }}</option><option value="__new">+ Add a category…</option></select></label>
          <label class="label">Paid to *<input v-model="f.payee" list="payees" maxlength="200" placeholder="Vendor, landlord, supplier"><datalist id="payees"><option v-for="p in data.options.payees" :key="p" :value="p" /></datalist></label><label class="label">Amount *<input v-model="f.amount" type="number" min="0" step="0.01"></label><label class="label">Currency<select v-model="f.currency"><option>USD</option><option>NGN</option><option>GBP</option><option>EUR</option></select></label>
          <label class="label">Method<select v-model="f.method"><option>Bank transfer</option><option>Card</option><option>Cash</option><option>Cheque</option><option>Direct debit</option><option>Other</option></select></label><label class="label">From account<select v-model="f.bank_account_id"><option value="">—</option><option v-for="a in data.options.accounts.filter((x) => !f.entity_id || x.entity_id === f.entity_id)" :key="a.id" :value="a.id">{{ a.name }} ({{ a.currency }})</option></select></label><label class="label">Reference<input v-model="f.reference" maxlength="120" placeholder="Transfer ref., invoice no."></label></div>
        <div v-if="nc.inForm" class="newc"><input v-model="nc.name" maxlength="60" placeholder="New category name" aria-label="New category"><select v-model="nc.line" aria-label="Statement line"><option v-for="(l, k) in cats?.lines ?? {}" :key="k" :value="k">{{ l }}</option></select><button class="btn sm" type="button" :disabled="nc.busy || nc.name.trim().length < 2" @click="addCat(true)">Add</button><button class="lk" type="button" @click="nc.inForm = false">Cancel</button><span v-if="nc.msg" class="error">{{ nc.msg }}</span></div>
        <label class="label">What it was for<textarea v-model="f.description" rows="2" maxlength="3000" /></label>
        <label class="label">Invoice or receipt (optional)<DropZone compact accept=".pdf,image/png,image/jpeg,image/webp" @change="pickFile" /></label>
        <div v-if="scan.busy || scan.read || scan.msg" class="scan" :class="{ bad: scanIssues.length }"><template v-if="scan.busy">Reading the receipt…</template><template v-else-if="scan.msg">{{ scan.msg }}</template>
          <template v-else-if="scan.read"><b>{{ scanIssues.length ? '⚠ Receipt does not match' : '✓ Receipt matches' }}</b><span v-if="scan.read.readable">Receipt no. {{ scan.read.number || '—' }} · total {{ scan.read.amount !== null ? money(scan.read.amount, scan.read.currency || f.currency) : '—' }}{{ scan.read.date ? ' · ' + scan.read.date : '' }}{{ scan.read.payee ? ' · ' + scan.read.payee : '' }}</span><span v-for="(x, i) in scanIssues" :key="i">{{ x }}</span></template></div>
        <p class="s">A payment voucher (PDF) is created and kept in Documents, and the payment is posted to the journals as an expense against cash at bank. An attached receipt is read and checked against the amount and reference.</p>
        <p v-if="dupe" class="dup">{{ dupe }} <button class="lk" @click="save(true)">Save anyway</button></p><p v-if="msg" class="error">{{ msg }}</p></div>
      <template #foot><button class="btn secondary" @click="f.open = false">Cancel</button><button class="btn" :disabled="busy || !f.payee || !f.amount" @click="save()">{{ busy ? 'Saving…' : 'Log payment and create voucher' }}</button></template>
    </AppModal>
    <AppModal :open="rc.open" title="Reconcile with a spreadsheet" wide @close="rc.open = false">
      <div class="fm"><p class="s">Upload a bank export, ledger, expense report, or a balance sheet / P&amp;L (Excel or CSV). AI compares it with the payments logged for the period and shows what matches, what is missing on either side, and any differences, so the books are not distorted.</p>
        <div class="g3"><label class="label">From<input v-model="rc.from" type="date"></label><label class="label">To<input v-model="rc.to" type="date"></label><label class="label">Entity<select v-model="rc.entity_id"><option value="">All entities</option><option v-for="e in data.options.entities" :key="e.id" :value="e.id">{{ e.name }}</option></select></label></div>
        <label class="label">Spreadsheet<DropZone compact accept=".xlsx,.csv" @change="rfile = ($event.target as HTMLInputElement).files?.[0] ?? null" /></label>
        <p v-if="rc.msg" class="error">{{ rc.msg }}</p>
        <div v-if="rec" class="rec"><p class="sum"><b>{{ rec.sheet_kind }}</b> · {{ rec.summary }}</p>
          <div class="rt"><span>Logged <b>{{ money(rec.totals.logged, rec.totals.currency || 'USD') }}</b></span><span>Sheet <b>{{ money(rec.totals.sheet, rec.totals.currency || 'USD') }}</b></span><span :class="{ bad: Math.abs(rec.totals.difference) > 0.01 }">Difference <b>{{ money(rec.totals.difference, rec.totals.currency || 'USD') }}</b></span></div>
          <h4 v-if="rec.missing_in_log.length">In the sheet but not logged ({{ rec.missing_in_log.length }})</h4><div v-for="(m, i) in rec.missing_in_log" :key="'m' + i" class="ri"><span>{{ m.date }} · {{ m.payee }} · {{ money(m.amount, m.currency || 'USD') }} <em>{{ m.sheet_row }}</em></span><button class="lk" @click="rc.open = false; open({ paid_on: m.date, payee: m.payee, amount: m.amount, currency: m.currency || 'USD', category: m.category && data.options.categories.includes(m.category) ? m.category : 'Other' })">Log it</button></div>
          <h4 v-if="rec.mismatched.length">Differences ({{ rec.mismatched.length }})</h4><div v-for="(m, i) in rec.mismatched" :key="'x' + i" class="ri"><span>{{ m.log_number }} ↔ {{ m.sheet_row }}: {{ m.issue }}</span></div>
          <h4 v-if="rec.missing_in_sheet.length">Logged but not in the sheet ({{ rec.missing_in_sheet.length }})</h4><div v-for="(m, i) in rec.missing_in_sheet" :key="'s' + i" class="ri"><span>{{ m.log_number }}{{ m.note ? ': ' + m.note : '' }}</span></div>
          <h4 v-if="rec.category_checks.length">By category</h4><div v-for="(c, i) in rec.category_checks" :key="'c' + i" class="ri"><span>{{ c.category }}: logged {{ money(c.logged, rec.totals.currency || 'USD') }}, sheet {{ money(c.sheet, rec.totals.currency || 'USD') }}{{ c.note ? ' · ' + c.note : '' }}</span></div>
          <p class="s">{{ rec.matched.length }} payment{{ rec.matched.length === 1 ? '' : 's' }} matched.</p></div></div>
      <template #foot><button class="btn secondary" @click="rc.open = false">Close</button><button class="btn" :disabled="rc.busy || !rfile" @click="reconcile">{{ rc.busy ? 'Reconciling…' : 'Reconcile' }}</button></template>
    </AppModal>
  </section>
</template>
